BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats12-q01', 'ノンパラメトリック検定',
   '新しい勉強法を試したクラス20人と、試していないクラス20人の平均点をt検定で比べた（前セットで扱った場面）。このt検定のような検定を使うとき、データについてこっそり置いている前提はどれ？',
   NULL::text,
   '["点数の分布が、山がひとつで左右対称に近い「正規分布」に沿っていること", "2つのクラスの人数が、最初から最後まで1人残らずぴったり同じであること", "点数の範囲が、テストの配点にかかわらず必ず0点から100点までに収まること", "2つのクラスの平均点が、検定を始める前からあらかじめほとんど同じであること"]',
   0, '[0]', 'single',
   '{"asked": "t検定のようなパラメトリック検定が、データについてあらかじめ置いている前提は何か。", "point": "パラメトリック検定は「データが正規分布に近い形をしている」ことを前提にして計算式を組み立てている。", "kid": "パラメトリック検定は、点数を集めるとだいたい真ん中が一番多くて、両端に行くほど少なくなる「山型」に散らばるはずだ、という思い込みのうえに計算式ができている。", "eg": "身長のようにたくさんの人を集めると、平均くらいの身長の人が一番多くて、すごく高い人・すごく低い人はだんだん少なくなる山型になる。t検定は、点数もこの身長のような山型に散らばっていることを当てにして計算している。", "terms": [["パラメトリック検定", "データが正規分布のような決まった形に従うと仮定して行う検定。t検定・分散分析など"], ["正規分布", "真ん中が一番多く、両端に行くほど少なくなる、左右対称の山型の散らばり方"]], "think": "なぜ「前提」という言葉を使うのかがカギ。t検定の計算式は、平均や標準偏差を使ってp値を出す。この計算式は、データが正規分布のような山型に散らばっているときにだけ正しく機能するように作られている。データの散らばり方が前提と大きく違っていると、計算式自体は数字を返すが、その数字（p値）の意味が保証されなくなる。だから使う前に「この前提が成り立っていそうか」を確かめる必要がある。", "vs": "「クラスの人数が同じ」「点数が0〜100点」「2群の平均が近い」はどれも検定の前提ではなく、たまたま今回の場面にありそうな条件にすぎない。前提として本当に効いてくるのは、分布の形（正規分布に近いか）のほう。", "why_asked": "この前提を知らないまま検定を使うと、「t検定さえ使えばどんなデータでも正しい結論が出る」と誤解してしまう。次の問いで、この前提が崩れたときにどうするかを学ぶための土台になる。", "usecase": "アンケートの回答やテストの点数を検定にかける前に、ヒストグラムを描いて山型に近いかをまず目で確認する、という実務上の一手間につながる。", "opt": ["正解。t検定などのパラメトリック検定は、データが正規分布のような山型に近いことを前提に計算式が組まれている。", "人数がぴったり同じかどうかは検定の前提ではない。人数が違っても使える検定はある。", "点数の範囲が0〜100点かどうかは前提にならない。テストの点数以外（体重・時間など）でも同じ検定を使う。", "2群の平均が近いかどうかはこれから検定で確かめたいことであって、あらかじめ置いておく前提ではない。"], "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">t検定などが当てにしている散らばり方</text><line x1=\"30\" y1=\"100\" x2=\"310\" y2=\"100\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><path d=\"M60,100 Q170,30 280,100 Z\" fill=\"#3b82f6\" opacity=\"0.18\"/><path d=\"M60,100 Q170,30 280,100\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"170\" y=\"118\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">真ん中が多く、両端が少ない「山型」＝正規分布</text><text x=\"170\" y=\"132\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">この形に近いことが、t検定の前提</text></svg>"}'),

  ('stats12-q02', 'ノンパラメトリック検定',
   '10人に商品の満足度を1(とても不満)〜5(とても満足)の5段階で答えてもらったところ、ほとんどの人が1か5を選び、真ん中の3を選んだ人はいなかった。正規分布の山型とはかけ離れたこの結果を、t検定のようなパラメトリック検定にそのままかけるのは避けたい。代わりに使う検定のグループを何と呼ぶ？',
   NULL::text,
   '["ノンパラメトリック検定（分布の形を仮定しない）", "重回帰分析（複数の変数から数値を予測する）", "ロジスティック回帰（0か1かの分類を予測する）", "分散分析、通常のANOVA（正規分布を前提とする）"]',
   0, '[0]', 'single',
   '{"asked": "正規分布の前提が崩れているデータに対して使う検定のグループの名前。", "point": "分布の形を前提にしない検定のグループを、ノンパラメトリック検定と呼ぶ。", "kid": "ノンパラメトリック検定は、「データが山型に散らばっているはず」という前提を置かずに使える検定のなかま。前提を置かない分、いろいろな形のデータに使える。", "eg": "パラメトリック検定が「この体育館は必ず長方形だ」と決めつけて面積を計算する方法だとしたら、ノンパラメトリック検定は形が長方形でもいびつな形でも使える、もっと汎用的な測り方のようなもの。", "terms": [["ノンパラメトリック検定", "データの分布の形を仮定しない検定のグループ"], ["尺度", "データの測り方の種類。順位や順序しか分からないデータもここに含まれる"]], "think": "なぜ前提を置かない検定が必要なのかがカギ。前の問いで見たとおり、t検定などは正規分布に近いことを前提に計算式が組まれている。今回のように1と5に極端に偏ったデータや、外れ値が多いデータ、あるいは満足度のように「順位や順序しかわからない」データでは、この前提がそもそも成り立たない。前提が崩れたまま計算式を当てはめても、出てきたp値の意味が保証されない。そこで、分布の形を前提にせずに計算できる、別の道具立てが必要になる。それがノンパラメトリック検定というグループ。", "vs": "重回帰分析・ロジスティック回帰は「複数の変数から予測する」ための手法であり、2群の差を比べる検定の代わりにはならない。分散分析(通常のANOVA)はt検定と同じくパラメトリック検定の仲間で、今回避けたい前提をやはり置いている。", "why_asked": "前提が崩れているのに気づかず、いつもの検定をそのまま使ってしまうのが実務でよくある間違い。まず「前提が崩れていないか」を確認し、崩れていたら別の道具があると知っていることが出発点になる。", "usecase": "満足度アンケートのような順序だけの回答、極端な外れ値を含む所得データ、サンプル数が少なくて分布の形が確認しづらいデータなど、幅広い場面で最初の選択肢として検討される。", "opt": ["正解。分布の形を前提にしない検定のグループを、ノンパラメトリック検定と呼ぶ。", "重回帰分析は複数の説明変数から数値を予測する手法。2つのグループの差を比べる検定の代わりにはならない。", "ロジスティック回帰は0か1かの分類を予測する手法。今回のような「差があるかどうか」を検定する話とは目的が違う。", "通常の分散分析(ANOVA)はt検定の仲間で、やはり正規分布を前提にしている。今回避けたい前提をそのまま置いている。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">満足度10人の回答（1〜5点）</text><line x1=\"30\" y1=\"92\" x2=\"310\" y2=\"92\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><rect x=\"36\" y=\"40\" width=\"40\" height=\"52\" fill=\"#60a5fa\"/><text x=\"56\" y=\"34\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">4人</text><text x=\"56\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1点</text><rect x=\"100\" y=\"78\" width=\"40\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"120\" y=\"72\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1人</text><text x=\"120\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">2点</text><text x=\"170\" y=\"88\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0人</text><text x=\"170\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">3点</text><rect x=\"200\" y=\"78\" width=\"40\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"220\" y=\"72\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1人</text><text x=\"220\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">4点</text><rect x=\"264\" y=\"40\" width=\"40\" height=\"52\" fill=\"#60a5fa\"/><text x=\"284\" y=\"34\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">4人</text><text x=\"284\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">5点</text><text x=\"170\" y=\"124\" fill=\"#c47070\" font-size=\"9.5\" text-anchor=\"middle\">真ん中が多い山型とは正反対の形</text></svg>"}'),

  ('stats12-q03', 'ノンパラメトリック検定',
   '5人の年収（万円）が 300, 320, 340, 360, 5000 だったとする。5000万円が1人だけ極端に大きく、正規分布の前提が崩れている。ノンパラメトリック検定の多くが、こういうデータに対して計算のいちばん最初にやることはどれ？',
   NULL::text,
   '["値をそのまま使わず、小さい順に並べた「順位」に置き換える", "全員の値を2乗して、単位をそろえてから比べる", "全員の値から平均を引いて、偏差の形にしてから比べる", "5000万円の人を1人だけ除いて、残り4人だけで計算する"]',
   0, '[0]', 'single',
   '{"asked": "ノンパラメトリック検定が、計算のいちばん最初にやっている共通の下ごしらえ。", "point": "値そのものではなく、小さい順に何番目かという「順位」に置き換えてから計算する。", "kid": "300万円・320万円・5000万円という金額そのものは使わずに、「1番小さい・2番目に小さい…」という順番の番号に置き換えてから計算を進める。", "eg": "徒競走の結果を発表するとき、タイムそのもの(12.3秒、12.5秒…)ではなく「1位、2位、3位…」という順位で発表するのに似ている。1位と2位の差が0.1秒でも1秒でも、順位の上では同じ「1つ違い」として扱われる。", "terms": [["順位", "値を小さい順（または大きい順）に並べたときの、何番目かという番号"], ["順位変換", "値そのものを、その順位の数字に置き換える下ごしらえ"]], "think": "なぜ値そのものではなく順位に変換するのかがカギ。300万円・320万円・340万円・360万円・5000万円をそのまま平均や分散の計算に使うと、5000万円という1つの極端な値に全体が大きく引っ張られてしまう。ところがこれを順位に置き換えると、1位・2位・3位・4位・5位という並びになり、5000万円は「1番大きい」という情報だけが残って、5000という金額の大きさそのものは計算に効かなくなる。極端な値の影響を先に抑えてから比べるために、値を順位に変換するのがノンパラメトリック検定の基本発想。", "vs": "2乗するのは分散の計算(符号を消すための工夫)、平均を引くのは偏差の計算で、どちらもパラメトリック検定側の下ごしらえ。極端な値を1人だけ除外するのは、データを勝手に捨てる行為で、順位に変換するのとは別物。", "why_asked": "この先に出てくるマン・ホイットニーのU検定・ウィルコクソンの符号順位検定・クラスカル・ウォリス検定は、すべてこの「順位に変換してから比べる」という同じ発想の上に成り立っている。ここを押さえておくと、この先の検定名を丸暗記せずに理解できる。", "usecase": "所得のように一部の人だけ極端に高い(低い)データ、アンケートの5段階評価のように順序しか意味を持たないデータを比べたいときに、この順位変換という考え方が土台になる。", "opt": ["正解。値そのものではなく、小さい順に並べた順位に置き換えてから計算するのが、ノンパラメトリック検定の基本発想。", "2乗するのは分散を求めるときの工夫であり、順位への置き換えとは別の下ごしらえ。", "平均を引いて偏差にするのは、パラメトリック検定側で使う下ごしらえ。順位への置き換えとは違う。", "極端な値を除外して計算するのは、データそのものを削ってしまう行為。順位に変換して活かしたまま使うのとは考え方が逆。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">値ではなく「順位」に置き換える</text><text x=\"30\" y=\"38\" fill=\"#8892a4\" font-size=\"9\">年収(万円)</text><text x=\"55\" y=\"56\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">300</text><text x=\"105\" y=\"56\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">320</text><text x=\"155\" y=\"56\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">340</text><text x=\"205\" y=\"56\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">360</text><text x=\"270\" y=\"56\" fill=\"#c47070\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"700\">5000</text><line x1=\"30\" y1=\"70\" x2=\"310\" y2=\"70\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"66\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">↓ 順位に置き換える ↓</text><text x=\"30\" y=\"92\" fill=\"#8892a4\" font-size=\"9\">順位</text><text x=\"55\" y=\"108\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">1位</text><text x=\"105\" y=\"108\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">2位</text><text x=\"155\" y=\"108\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">3位</text><text x=\"205\" y=\"108\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">4位</text><text x=\"270\" y=\"108\" fill=\"#60a5fa\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">5位</text><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">5000万円の大きさそのものは効かなくなる</text></svg>"}'),

  ('stats12-q04', 'ノンパラメトリック検定',
   '広告Aを見せたグループと広告Bを見せたグループ(対応のない別々の人たち)で、商品への関心度を5段階評価で答えてもらった。正規分布とは言えないこのデータを、順位に変換してから2つのグループを比べたい。使う検定はどれ？',
   NULL::text,
   '["マン・ホイットニーのU検定（対応なし2群）", "ウィルコクソンの符号順位検定（対応あり2群）", "クラスカル・ウォリス検定（対応なし3群以上）", "カイ二乗検定（カテゴリの人数の偏り）"]',
   0, '[0]', 'single',
   '{"asked": "対応のない2つのグループを、順位を使って比べる検定の名前。", "point": "対応のない2群を順位で比べるならマン・ホイットニーのU検定。t検定のノンパラメトリック版にあたる。", "kid": "マン・ホイットニーのU検定は、「広告Aを見た人たち」と「広告Bを見た人たち」のように、まったく別々の人からなる2つのグループを、順位に変換したうえで比べる検定。", "eg": "赤組と白組で徒競走のタイムそのものではなく順位を比べて、「赤組のほうが全体的に上位に来ているか」を判定するイメージ。赤組と白組は別々の人たちで、同じ人が両方の組にいるわけではない。", "terms": [["対応のない2群", "比べる2つのグループが、まったく別々の人（または対象）からできていること"], ["マン・ホイットニーのU検定", "対応のない2群を、順位に変換したうえで比べるノンパラメトリック検定"]], "think": "なぜ「t検定のノンパラメトリック版」と呼ばれるのかがカギ。パラメトリックな世界で、対応のない2群の平均を比べたいときに使うのがt検定だった。マン・ホイットニーのU検定は、これと同じ「対応のない2群を比べる」という役割を担いながら、値そのものではなく順位に変換して計算する点だけが違う。役割は同じで、正規分布の前提を置くかどうかが分かれ目になっている。", "vs": "ウィルコクソンの符号順位検定は、同じ人の前後を比べる「対応のある」場面で使う点が違う。クラスカル・ウォリス検定は2群ではなく3群以上を比べるときに使う。カイ二乗検定は数値の大小ではなく、カテゴリごとの人数の偏りを調べる検定で、そもそも扱うデータの種類が違う。", "why_asked": "「対応があるかないか」「比べるのは2群か3群以上か」という場面の違いによって、使うノンパラメトリック検定の名前が変わる。この場面と名前の対応を取り違えるのが典型的な間違い。", "usecase": "2種類の広告・2つの薬・2つの教材のように、別々の人やグループを比べたいが、正規分布の前提を置きたくない(あるいは順位でしか答えられないアンケートを使う)場面で使う。", "opt": ["正解。マン・ホイットニーのU検定は、対応のない2群を順位に変換して比べる、t検定のノンパラメトリック版。", "ウィルコクソンの符号順位検定は、同じ人の前後を比べる「対応のある」場面で使う検定。今回の広告A・Bは別々の人なので対応がない。", "クラスカル・ウォリス検定は3群以上を比べるときに使う検定。今回は広告A・Bの2群なので当てはまらない。", "カイ二乗検定は関心度の大小ではなく、回答のカテゴリごとの人数の偏りを調べる検定。今回のように順位で比べたい場面には使わない。"], "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">対応のない2グループを順位で比べる</text><text x=\"90\" y=\"36\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">広告Aグループ</text><circle cx=\"50\" cy=\"56\" r=\"5\" fill=\"#3b82f6\"/><circle cx=\"75\" cy=\"56\" r=\"5\" fill=\"#3b82f6\"/><circle cx=\"100\" cy=\"56\" r=\"5\" fill=\"#3b82f6\"/><circle cx=\"125\" cy=\"56\" r=\"5\" fill=\"#3b82f6\"/><text x=\"250\" y=\"36\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">広告Bグループ</text><circle cx=\"215\" cy=\"56\" r=\"5\" fill=\"#c9a04a\"/><circle cx=\"240\" cy=\"56\" r=\"5\" fill=\"#c9a04a\"/><circle cx=\"265\" cy=\"56\" r=\"5\" fill=\"#c9a04a\"/><circle cx=\"290\" cy=\"56\" r=\"5\" fill=\"#c9a04a\"/><text x=\"170\" y=\"56\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">別々の人</text><line x1=\"30\" y1=\"80\" x2=\"310\" y2=\"80\" stroke=\"#2a2f3f\"/><text x=\"55\" y=\"96\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"middle\">A 1位</text><text x=\"105\" y=\"96\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"middle\">A 2位</text><text x=\"165\" y=\"96\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">B 3位</text><text x=\"220\" y=\"96\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"middle\">A 4位</text><text x=\"270\" y=\"96\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">B 5位</text><text x=\"170\" y=\"118\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">全員をまとめて順位づけ、どちらに偏るかを見る</text></svg>"}'),

  ('stats12-q05', 'ノンパラメトリック検定',
   '同じ8人に、ダイエット講座の前と後で体重を測った。同じ人の「前」と「後」というペアになっているデータで、正規分布の前提を置かずに差を比べたい。使う検定はどれ？',
   NULL::text,
   '["ウィルコクソンの符号順位検定（対応あり2群）", "マン・ホイットニーのU検定（対応なし2群）", "クラスカル・ウォリス検定（対応なし3群以上）", "スピアマンの順位相関係数（2つの量の関係）"]',
   0, '[0]', 'single',
   '{"asked": "同じ人の前後のような「対応のある」2つのデータを、順位を使って比べる検定の名前。", "point": "対応のある2群(同じ人の前後など)を順位で比べるならウィルコクソンの符号順位検定。", "kid": "ウィルコクソンの符号順位検定は、「同じ人のダイエット前と後」のように、1人ひとりの中で対になっているデータを、順位に変換して比べる検定。", "eg": "8人それぞれの「体重の変化量」を計算してから、その変化量が0からどれくらい離れているかを順位づけして比べるイメージ。8人それぞれの中で前後を比べている点が、マン・ホイットニーのU検定との一番の違い。", "terms": [["対応のある2群", "同じ人（または同じ対象）から、条件を変えて2回とったデータの組"], ["ウィルコクソンの符号順位検定", "対応のある2群を、順位に変換したうえで比べるノンパラメトリック検定"]], "think": "なぜマン・ホイットニーのU検定ではなく、別の名前の検定を使うのかがカギ。マン・ホイットニーのU検定は「広告Aグループ」と「広告Bグループ」のように、比べる2つの集まりがまったく別の人たちであることを前提にしている。しかし今回は「同じ8人」の前と後を比べているので、AグループとBグループのような別人同士の比較ではなく、1人ひとりの中の変化を見ることになる。この「同じ人の中の変化」という対応関係を活かして計算するために、マン・ホイットニーとは別の、対応のあるデータ専用の検定が用意されている。", "vs": "マン・ホイットニーのU検定は対応のない別々の人たちを比べる検定で、今回のような同じ人の前後比較には使わない。クラスカル・ウォリス検定は3群以上を比べる検定、スピアマンの順位相関係数は2つの量の関係の強さを調べるもので、どちらも今回の「同じ人の前後の差」を検定する目的とは違う。", "why_asked": "「対応のある・ない」を取り違えると、検定名を正しく選べない。同じ人を繰り返し測っているのか、別々の人を比べているのかを最初に見極める習慣が、この先すべてのノンパラメトリック検定選びで必要になる。", "usecase": "研修の前後でのテストの点数、治療の前後での症状の重さ、CMを見る前と後での好感度など、同じ対象を条件を変えて2回測る場面で使う。", "opt": ["正解。ウィルコクソンの符号順位検定は、同じ人の前後のような対応のある2群を、順位に変換して比べる検定。", "マン・ホイットニーのU検定は対応のない別々の2グループを比べる検定。今回は同じ8人の前後なので対応がある。", "クラスカル・ウォリス検定は3群以上を比べる検定。今回は「前」と「後」の2群なので当てはまらない。", "スピアマンの順位相関係数は2つの量のあいだの関係の強さを調べるもので、前後の差を検定する話とは目的が違う。"], "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ8人の「前」と「後」を比べる</text><text x=\"70\" y=\"36\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">講座の前</text><text x=\"270\" y=\"36\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">講座の後</text><circle cx=\"70\" cy=\"54\" r=\"5\" fill=\"#60a5fa\"/><circle cx=\"270\" cy=\"50\" r=\"5\" fill=\"#3b82f6\"/><line x1=\"75\" y1=\"54\" x2=\"265\" y2=\"50\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"170\" y=\"46\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">Aさん</text><circle cx=\"70\" cy=\"78\" r=\"5\" fill=\"#60a5fa\"/><circle cx=\"270\" cy=\"70\" r=\"5\" fill=\"#3b82f6\"/><line x1=\"75\" y1=\"78\" x2=\"265\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"170\" y=\"70\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">Bさん</text><circle cx=\"70\" cy=\"102\" r=\"5\" fill=\"#60a5fa\"/><circle cx=\"270\" cy=\"96\" r=\"5\" fill=\"#3b82f6\"/><line x1=\"75\" y1=\"102\" x2=\"265\" y2=\"96\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"170\" y=\"94\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">Cさん</text><text x=\"170\" y=\"124\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">1人ずつの中の変化を、順位にして比べる</text></svg>"}'),

  ('stats12-q06', 'ノンパラメトリック検定',
   '3種類の教材A・B・Cをそれぞれ別のクラスで使い、テストの点数を比べたい。点数の分布が正規分布とは言えないため、順位に変換してから3つのグループを比べたい。使う検定はどれ？',
   NULL::text,
   '["クラスカル・ウォリス検定", "マン・ホイットニーのU検定", "ウィルコクソンの符号順位検定", "スピアマンの順位相関係数"]',
   0, '[0]', 'single',
   '{"asked": "3つ以上のグループを、順位を使って比べる検定の名前。", "point": "3群以上を順位で比べるならクラスカル・ウォリス検定。分散分析(ANOVA)のノンパラメトリック版にあたる。", "kid": "クラスカル・ウォリス検定は、教材A・B・Cのクラスのように、3つ以上のグループをまとめて、順位に変換したうえで比べる検定。", "eg": "3つの組(A組・B組・C組)を1つの徒競走に一緒に走らせて、それぞれの組の順位が全体的にどこに偏っているかを見るイメージ。2つの組だけを比べるマン・ホイットニーとは、比べる組の数が違う。", "terms": [["クラスカル・ウォリス検定", "3群以上を、順位に変換したうえで比べるノンパラメトリック検定"], ["分散分析(ANOVA)", "3群以上の平均を比べるパラメトリック検定。クラスカル・ウォリス検定はこのノンパラメトリック版"]], "think": "なぜマン・ホイットニーのU検定を3回繰り返すのではダメなのかがカギ。A対B、A対C、B対Cと2群ずつの検定を3回繰り返すと、前のセットの多重検定の問題(何度も検定を繰り返すと「たまたま有意」が出やすくなる)が起きてしまう。クラスカル・ウォリス検定は、A・B・Cの点数をまとめて1回だけ順位づけし、3つのグループの順位の偏りをまとめて1回の検定で調べる。だから2群用の検定を繰り返すよりも安全に「3群のどこかに差がありそうか」を確かめられる。", "vs": "マン・ホイットニーのU検定は2群専用で、3群を比べたいときにそのまま使うと繰り返し検定の問題が起きる。ウィルコクソンの符号順位検定は対応のある2群専用。スピアマンの順位相関係数はグループの差ではなく、2つの量の関係の強さを見るためのもので目的が違う。", "why_asked": "「2群ならマン・ホイットニー、3群以上ならクラスカル・ウォリス」という使い分けは、パラメトリック側の「2群ならt検定、3群以上なら分散分析」という使い分けとそっくり対応している。この対応関係を知っていると、検定名を丸暗記せずに選べる。", "usecase": "3種類以上の教材・薬・広告のように、比べたいグループが3つ以上あり、かつ正規分布の前提を置きたくない場面で使う。", "opt": ["正解。クラスカル・ウォリス検定は3群以上を順位に変換して比べる、分散分析(ANOVA)のノンパラメトリック版。", "マン・ホイットニーのU検定は2群専用の検定。3群を比べたい今回のような場面にそのまま使うのは適さない。", "ウィルコクソンの符号順位検定は対応のある2群専用の検定。今回のような別クラス3群の比較には使わない。", "スピアマンの順位相関係数はグループ間の差ではなく、2つの量のあいだの関係の強さを調べるもので目的が違う。"], "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">3グループをまとめて順位づけする</text><text x=\"60\" y=\"36\" fill=\"#3b82f6\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">教材A</text><text x=\"170\" y=\"36\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">教材B</text><text x=\"280\" y=\"36\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">教材C</text><circle cx=\"40\" cy=\"56\" r=\"5\" fill=\"#3b82f6\"/><circle cx=\"75\" cy=\"56\" r=\"5\" fill=\"#3b82f6\"/><circle cx=\"150\" cy=\"56\" r=\"5\" fill=\"#60a5fa\"/><circle cx=\"190\" cy=\"56\" r=\"5\" fill=\"#60a5fa\"/><circle cx=\"260\" cy=\"56\" r=\"5\" fill=\"#c9a04a\"/><circle cx=\"300\" cy=\"56\" r=\"5\" fill=\"#c9a04a\"/><line x1=\"30\" y1=\"80\" x2=\"310\" y2=\"80\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"78\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">↓ 全員まとめて1〜6位に順位づけ ↓</text><text x=\"170\" y=\"104\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">3グループの順位の偏りを、1回の検定でまとめて見る</text><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">2群の検定を3回繰り返すより安全</text></svg>"}'),

  ('stats12-q07', 'ノンパラメトリック検定',
   '9人分のデータでは勉強時間と得点にほとんど関係が見えなかった。そこにもう1人、極端に勉強時間が長く得点も高い人を1人加えたら、ピアソンの相関係数が0.8まで跳ね上がった（前セットで扱った場面）。この1人の外れ値に引きずられにくい、順位をもとにした相関係数を何と呼ぶ？',
   NULL::text,
   '["スピアマンの順位相関係数（順位で見る相関）", "決定係数（回帰直線がどれだけ当てはまるか）", "分散（データ1つのばらつきの大きさ）", "標準偏差（ばらつきを元の単位に戻した値）"]',
   0, '[0]', 'single',
   '{"asked": "値そのものではなく、順位をもとに計算する相関係数の名前。", "point": "値ではなく順位をもとに計算する相関係数がスピアマンの順位相関係数。外れ値や非直線の関係にも強い。", "kid": "スピアマンの順位相関係数は、勉強時間や得点そのものの数字ではなく、「何番目に多いか・高いか」という順位に置き換えたうえで、2つのものごとの関係の強さを計算する数。", "eg": "10人のかけっこの記録を、タイムそのもの(秒)ではなく順位(1位・2位・3位…)で比べるようなもの。1人だけ極端に速い(または遅い)人がいても、その人の順位は「1位」や「10位」という1つの席にしか座らないので、タイムの数字ほど全体を引きずらない。", "terms": [["ピアソンの相関係数", "値そのものを使って計算する、直線的な関係の強さを表す相関係数"], ["スピアマンの順位相関係数", "値を順位に置き換えてから計算する相関係数。外れ値の影響を受けにくい"]], "think": "なぜ順位に変換すると外れ値に引きずられにくくなるのかがカギ。ピアソンの相関係数は値そのものを使うので、1人だけ極端に大きい値があると、その1つの値の大きさが計算全体を強く引っ張ってしまう。ところがスピアマンの順位相関係数は、その極端な人も「勉強時間が一番多い人」「得点が一番高い人」という順位、つまり10人の中の1つの順番としてしか扱わない。値の大きさそのもの(何時間・何点)は計算に効かず、順位という決まった範囲の数字に置き換わっているので、1人の極端な値が全体を引きずる度合いが小さくなる。", "vs": "決定係数は回帰直線の当てはまりの良さを表す指標で、相関の強さそのものとは役割が違う。分散・標準偏差はデータの散らばりの大きさを表す指標で、2つの量の関係の強さとは別のもの。", "why_asked": "外れ値に弱いピアソンの相関係数だけを知っていると、極端な値が1つ混じっただけのデータで「強い関係がある」と誤解しやすい。順位ベースの選択肢があることを知っていれば、外れ値が疑わしいときの確認手段になる。", "usecase": "所得と満足度のように一部だけ極端な値が混じりやすいデータ、直線ではなく右肩上がりの曲線的な関係を調べたいデータで、ピアソンの相関係数の代わりに使われる。", "opt": ["正解。値ではなく順位に置き換えてから計算するのがスピアマンの順位相関係数。外れ値や非直線の関係にも強い。", "決定係数は回帰直線がデータにどれだけ当てはまっているかを表す指標で、相関係数とは別の役割を持つ数。", "分散はデータ1つの散らばりの大きさを表す指標で、2つの量の関係の強さを表すものではない。", "標準偏差も分散と同じくデータ1つの散らばりの大きさを表す指標で、2つの量の関係の強さとは別のもの。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">外れ値1人が相関係数を引きずる／引きずらない</text><text x=\"90\" y=\"32\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">値そのもの（ピアソン）</text><line x1=\"30\" y1=\"90\" x2=\"150\" y2=\"90\" stroke=\"#2a2f3f\"/><line x1=\"30\" y1=\"90\" x2=\"30\" y2=\"40\" stroke=\"#2a2f3f\"/><circle cx=\"45\" cy=\"82\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"55\" cy=\"78\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"65\" cy=\"84\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"75\" cy=\"76\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"140\" cy=\"46\" r=\"4.5\" fill=\"#c47070\"/><line x1=\"75\" y1=\"76\" x2=\"140\" y2=\"46\" stroke=\"#c47070\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/><text x=\"90\" y=\"104\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">1人が線を大きく引っぱる</text><text x=\"250\" y=\"32\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">順位（スピアマン）</text><line x1=\"190\" y1=\"90\" x2=\"310\" y2=\"90\" stroke=\"#2a2f3f\"/><line x1=\"190\" y1=\"90\" x2=\"190\" y2=\"40\" stroke=\"#2a2f3f\"/><circle cx=\"205\" cy=\"78\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"220\" cy=\"70\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"235\" cy=\"62\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"250\" cy=\"54\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"300\" cy=\"46\" r=\"4.5\" fill=\"#6ab08d\"/><text x=\"250\" y=\"104\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">1位という順位だけが効く</text></svg>"}'),

  ('stats12-q08', 'ノンパラメトリック検定',
   'カイ二乗検定には主に2つの使い方がある。①「カレー・ラーメン・うどんの回答者数の偏りが、理論上の均等な割合とずれていないか」を調べる使い方と、②「性別と好きな給食の種類のあいだに関係があるか」を調べる使い方。①と②の呼び名の組み合わせとして正しいのはどれ？',
   NULL::text,
   '["①適合度検定 ②独立性検定", "①独立性検定 ②適合度検定", "①適合度検定 ②適合度検定", "①独立性検定 ②独立性検定"]',
   0, '[0]', 'single',
   '{"asked": "カイ二乗検定の2つの使い方、適合度検定と独立性検定の呼び分け。", "point": "1つの変数の分布が理論どおりかを見るのが適合度検定、2つの変数に関係があるかを見るのが独立性検定。", "kid": "同じカイ二乗検定という道具でも、聞いている質問の中身によって2つの呼び名を使い分ける。「1つのものの割合が、思っていた割合とずれていないか」を聞くのが適合度検定、「2つのものごとが関係しているか」を聞くのが独立性検定。", "eg": "適合度検定は「このサイコロは本当にどの目も1/6ずつ出ているか」を1つのサイコロだけで確かめる話。独立性検定は「男子と女子で、好きな給食の種類に違いがあるか」のように、2つのものごと(性別と好きな給食)を組み合わせて確かめる話。見ているものの数が1つか2つかで名前が分かれる。", "terms": [["適合度検定", "1つの変数の分布(割合)が、理論どおりの割合とずれていないかを調べるカイ二乗検定の使い方"], ["独立性検定", "2つの変数のあいだに関係(偏り)があるかを調べるカイ二乗検定の使い方"]], "think": "なぜ同じカイ二乗検定なのに2つの名前があるのかがカギ。①は「カレー・ラーメン・うどん」という1つの変数(好きな給食の種類)だけを見て、その割合が理論上の均等な割合とずれていないかを調べている。見ている変数は1つだけ。②は「性別」と「好きな給食」という2つの変数を見て、この2つが独立(無関係)かどうかを調べている。見ている変数の数が1つか2つかという違いが、そのまま適合度検定・独立性検定という呼び名の違いになっている。計算の骨組み(理論値とのずれを2乗して集計する)自体は共通しているが、何を確かめたいかで名前が変わる。", "vs": "適合度検定と独立性検定は、どちらも「観測された人数」と「理論上の人数」のずれを同じような式で計算する点は共通しているが、確かめたい対象が1変数か2変数かで呼び名が違う。名前を入れ替えて覚えると混同する。", "why_asked": "「カイ二乗検定」と一括りにして覚えていると、①と②のどちらの場面で使うべき検定なのか判断できなくなる。1変数か2変数かをまず確認する癖をつけることが、正しく使い分ける第一歩になる。", "usecase": "適合度検定は、サイコロやくじの出目が理論どおりかを確かめる場面、アンケートの回答比率が想定どおりかを確かめる場面で使う。独立性検定は、性別と購買行動、年代とアンケート回答のように、2つのカテゴリ変数の関係を調べる場面で使う。", "opt": ["正解。1つの変数(好きな給食)の分布を理論値と比べる①は適合度検定、2つの変数(性別と好きな給食)の関係を見る②は独立性検定。", "①と②の呼び名がちょうど入れ替わっている。1変数を理論値と比べるのが適合度検定、2変数の関係を見るのが独立性検定。", "②は2つの変数(性別と好きな給食)の関係を見ており、1変数の分布を見る適合度検定ではなく独立性検定にあたる。", "①は1つの変数(好きな給食)の分布を理論値と比べており、2変数の関係を見る独立性検定ではなく適合度検定にあたる。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じカイ二乗検定、見ている変数の数が違う</text><text x=\"90\" y=\"36\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">① 適合度検定</text><rect x=\"35\" y=\"48\" width=\"110\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"90\" y=\"62\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">好きな給食（1つの変数）</text><text x=\"90\" y=\"84\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">理論上の割合とずれてる？</text><text x=\"250\" y=\"36\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">② 独立性検定</text><rect x=\"195\" y=\"48\" width=\"52\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"221\" y=\"62\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">性別</text><rect x=\"253\" y=\"48\" width=\"52\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"279\" y=\"62\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">給食</text><text x=\"250\" y=\"84\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">2つの変数に関係がある？</text><line x1=\"170\" y1=\"30\" x2=\"170\" y2=\"96\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"114\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">計算の骨組みは共通、見る変数の数が違うだけ</text></svg>"}'),

  ('stats12-q09', 'ノンパラメトリック検定',
   '5人の年収（万円）が 300, 320, 340, 360, 5000 のとき、平均は1264万円になり、実際の5人のほとんどの感覚(300〜360万円)からかけ離れる。一方、中央値は340万円で、5000万円という外れ値の影響をあまり受けない。ノンパラメトリック検定が外れ値に強いのは、これと同じどんな理由から？',
   NULL::text,
   '["値そのものでなく順位に変換するので、極端な値の大きさが計算に反映されにくくなるから", "計算の前に外れ値を自動的に見つけて、こっそり除外する仕組みが入っているから", "サンプルの人数を、外れ値がある分だけ自動的に多めに数え直す仕組みがあるから", "外れ値がある場合だけ、有意水準を5%から1%へと自動的に厳しく変える仕組みがあるから"]',
   0, '[0]', 'single',
   '{"asked": "ノンパラメトリック検定が外れ値の影響を受けにくいのは、どういう仕組みによるものか。", "point": "中央値が「順番の真ん中」しか見ないのと同じく、ノンパラメトリック検定も値の大きさではなく順位しか見ないので、外れ値の影響が抑えられる。", "kid": "中央値は5000万円の人がいても「一番大きい人」という順番の情報しか使わないので、1264万円まで引きずられた平均ほどは動かない。ノンパラメトリック検定も同じように、値の大きさそのものではなく順位を使うので、極端な値に振り回されにくい。", "eg": "運動会の順位発表で、1位の子が他の子よりどれだけ速かったか(タイム差)は発表されず、「1位」というひとことで終わる。タイム差がどれだけ開いていても、発表される情報は「1位」という同じ1つの席なので、極端な速さが目立ちすぎることがない。", "terms": [["中央値", "データを大きさの順に並べたとき、ちょうど真ん中に来る値"], ["ロバスト性", "外れ値のような極端な値があっても、結果が大きく変わりにくい性質"]], "think": "なぜ順位に変換すると外れ値に強くなるのかがカギ。平均は「5000万円」という値の大きさをそのまま合計に足し込むので、この1つの値がとても大きいと合計、ひいては平均を大きく引き上げてしまう。中央値は値の大きさを見ず、「大きい順に並べたとき真ん中は何番目か」という順位だけを見るので、5000万円がどれだけ極端に大きくても「一番大きい」という1つの順位としてしか扱われず、真ん中の値にはほとんど影響しない。ノンパラメトリック検定も同じ仕組みで、q03で見たとおり値を順位に変換してから計算するので、極端な値の「大きさ」そのものは検定の結果にほとんど効かなくなる。", "vs": "「外れ値を自動的に除外する」「人数を数え直す」「有意水準を自動的に変える」は、いずれもノンパラメトリック検定が実際にやっていることではない。データを削ったり検定のルールをこっそり変えたりするのではなく、値の使い方(順位に変換する)を変えているだけ。", "why_asked": "「なぜノンパラメトリック検定は外れ値に強いのか」という理由を知らずに丸暗記していると、平均と中央値の話(データのようすの基礎編)とのつながりに気づけない。同じ「順位を使う・使わない」という発想が形を変えて出てきているだけだと分かると、理解がつながる。", "usecase": "所得・待ち時間・売上のように一部だけ極端に大きい(小さい)値が混じりやすいデータを扱うとき、平均や通常の検定の代わりに中央値やノンパラメトリック検定を選ぶ判断の理由になる。", "opt": ["正解。値そのものでなく順位に変換するので、極端な値の大きさが計算にそのまま反映されにくくなる。中央値が外れ値に強いのと同じ発想。", "外れ値を自動的に見つけて除外する仕組みは無い。ノンパラメトリック検定は外れ値も含めた全員を順位に変換して使う。", "サンプルの人数を外れ値の分だけ多く数え直す仕組みは無い。人数はそのまま、値の扱い方(順位への変換)だけが変わる。", "有意水準を外れ値の有無で自動的に変える仕組みは無い。有意水準は検定の前にあらかじめ決めておく別の値。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">平均と中央値、5000万円にどれだけ引きずられる？</text><line x1=\"30\" y1=\"48\" x2=\"310\" y2=\"48\" stroke=\"#2a2f3f\"/><circle cx=\"45\" cy=\"48\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"65\" cy=\"48\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"85\" cy=\"48\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"105\" cy=\"48\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"290\" cy=\"48\" r=\"5\" fill=\"#c47070\"/><text x=\"290\" y=\"38\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">5000万円</text><polygon points=\"210,50 202,66 218,66\" fill=\"#c47070\"/><text x=\"210\" y=\"80\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">平均1264万円</text><text x=\"210\" y=\"92\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">大きく引きずられる</text><polygon points=\"85,50 77,66 93,66\" fill=\"#6ab08d\"/><text x=\"85\" y=\"80\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">中央値340万円</text><text x=\"85\" y=\"92\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">ほぼ動かない</text><text x=\"170\" y=\"120\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">順位しか見ないので、大きさに引きずられない</text></svg>"}'),

  ('stats12-q10', 'ノンパラメトリック検定',
   'ここまでの内容をまとめる。パラメトリック検定とノンパラメトリック検定のどちらを使うべきかを判断するとき、まず確認すべき組み合わせとして最も適切なのはどれ？',
   NULL::text,
   '["データの分布の形（正規分布に近いか）、標本の大きさ、データの尺度（数値か順位か）", "検定をしたあとに出てくるp値の大きさ、効果量、信頼区間の幅", "有意水準をいくつに設定したか、片側検定か両側検定か、帰無仮説の文章の長さ", "データを集めるのにかかった日数、入力に使ったソフトの種類、ファイル形式（csvかどうか）"]',
   0, '[0]', 'single',
   '{"asked": "パラメトリック検定とノンパラメトリック検定、どちらを選ぶかの判断基準のまとめ。", "point": "分布の形・標本サイズ・尺度の3つを確認して、正規分布に近く数値データで標本もある程度あればパラメトリック、そうでなければノンパラメトリックを選ぶ。", "kid": "どちらの検定を使うか迷ったら、①点数の散らばりが山型(正規分布)に近いか、②集めた人数が十分多いか、③データが数値なのか、それとも順位や順番しか意味を持たないデータなのか、の3つを確認する。", "eg": "服のサイズを選ぶときに「身長」「体型」「用途」の3つを見て決めるのと同じで、検定選びも1つの基準だけでなく、分布の形・標本の大きさ・尺度の3つを合わせて確認して決める。", "terms": [["標本サイズ", "検定に使うデータの人数（個数）"], ["尺度", "データの測り方の種類。数値そのものが意味を持つデータもあれば、順位や順序しか意味を持たないデータもある"]], "think": "なぜこの3つを確認するのかがカギ。q01で見たとおり、パラメトリック検定は正規分布に近いことを前提にしている。データが山型に近くない、あるいは満足度アンケートのように順位しか意味を持たない尺度なら、その前提がそもそも成り立たないので、q02〜q08で見たノンパラメトリック検定を選ぶことになる。また標本サイズが少ないと「本当に正規分布に近いのか」自体を確かめにくいため、標本が小さいときは前提を置かずに済むノンパラメトリック検定のほうが安全な選択になりやすい。分布の形・標本サイズ・尺度という3つの確認を飛ばして「いつものt検定」を機械的に使ってしまうと、q01で確認した前提が崩れたまま検定をかけることになり、出てきたp値の意味が保証されなくなる。", "vs": "p値・効果量・信頼区間の幅は、検定を行ったあとに出てくる結果であり、検定を選ぶ前の基準にはならない。有意水準や片側・両側の違いは、検定の種類を選んだ「あと」に決める設定であり、パラメトリックかノンパラメトリックかを選ぶ基準そのものではない。データを集めた日数やソフトの種類、ファイル形式も、データそのものの性質とは無関係な事情。", "why_asked": "この問題集で学んだ検定を実際の場面で使うとき、名前を覚えているだけでは足りず、「どちらを選ぶべきか」を自分で判断できる必要がある。ここまでの用語(正規分布・標本・尺度)をつなげて判断基準にできるかを確かめる、このセットのまとめの問い。", "usecase": "実際にデータを集めて検定を選ぶとき、まずヒストグラムで分布の形を確認し、人数と尺度をあわせて見て、パラメトリック検定とノンパラメトリック検定のどちらを使うかを決める、という実務の手順そのものになる。", "opt": ["正解。分布の形・標本サイズ・尺度の3つを確認して、パラメトリックとノンパラメトリックのどちらを使うか判断する。", "p値・効果量・信頼区間の幅は、検定を行ったあとに出てくる結果であって、検定の前にデータの性質から確認しておく基準ではない。", "有意水準や片側・両側の違いは、検定の種類を選んだあとに決める設定であり、検定の種類そのものを選ぶ基準ではない。", "データを集めた日数やソフトの種類、ファイル形式は、データそのものの性質とは関係のない事情で、検定選びの基準にはならない。"], "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">検定選びの3つの確認ポイント</text><rect x=\"20\" y=\"28\" width=\"90\" height=\"40\" fill=\"none\" stroke=\"#2a2f3f\" rx=\"4\"/><text x=\"65\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">分布の形</text><text x=\"65\" y=\"60\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">正規分布に近い？</text><rect x=\"125\" y=\"28\" width=\"90\" height=\"40\" fill=\"none\" stroke=\"#2a2f3f\" rx=\"4\"/><text x=\"170\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">標本サイズ</text><text x=\"170\" y=\"60\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">人数は十分？</text><rect x=\"230\" y=\"28\" width=\"90\" height=\"40\" fill=\"none\" stroke=\"#2a2f3f\" rx=\"4\"/><text x=\"275\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">尺度</text><text x=\"275\" y=\"60\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">数値？順位？</text><line x1=\"170\" y1=\"68\" x2=\"170\" y2=\"84\" stroke=\"#8892a4\"/><rect x=\"30\" y=\"88\" width=\"120\" height=\"32\" fill=\"#3b82f6\" opacity=\"0.25\" rx=\"4\"/><text x=\"90\" y=\"102\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">前提を満たす</text><text x=\"90\" y=\"114\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">パラメトリック検定</text><rect x=\"190\" y=\"88\" width=\"120\" height=\"32\" fill=\"#c9a04a\" opacity=\"0.25\" rx=\"4\"/><text x=\"250\" y=\"102\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">前提が崩れている</text><text x=\"250\" y=\"114\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">ノンパラメトリック検定</text><text x=\"170\" y=\"136\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">3つの確認結果で、どちらを選ぶか決まる</text></svg>"}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
